"""Build the Plotform Atelier adaptation of Dante into portable HTML/CSS.

GPL-3.0. Original Dante source provenance and complete source included alongside.
Run from this directory: python3 build.py [output-directory]
"""
from pathlib import Path
from html import escape
import sys, shutil

HERE = Path(__file__).parent
OUT = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / 'dist'
OUT.mkdir(parents=True, exist_ok=True)
shutil.copytree(HERE / 'assets', OUT / 'assets', dirs_exist_ok=True)
shutil.copyfile(HERE / 'style.css', OUT / 'style.css')
PROJECTS = [
    dict(slug='northstar', name='Northstar', image='project-1.jpg', category='Identity · Art direction', line='A clear point of view.', intro='An identity study shaped by the meeting of land and sea. Quiet confidence, a precise mark, and space to breathe.', brief='Find a visual language that feels grounded without standing still.', idea='A strong, geometric mark sits against the movement of the natural world. The contrast gives the identity its character: precise, but never rigid.', palette=['#1d2624','#eff0e9','#929b93']),
    dict(slug='altitude', name='Altitude', image='project-2.jpg', category='Strategy · Visual language', line='Room for a bigger idea.', intro='A study in scale and contrast. An expansive photographic world meets an energetic, unmistakable accent.', brief='Build a visual world that feels open, ambitious, and easy to recognise.', idea='A restrained monochrome foundation allows one vivid colour to do the work. Generous compositions keep the landscape at the centre of the story.', palette=['#303329','#c1f42a','#f1f2ee']),
    dict(slug='fieldwork', name='Fieldwork', image='project-4.jpg', category='Brand world · Digital direction', line='A natural sense of order.', intro='A brand-world study informed by the patterns of cultivation: individual details finding their place in a larger system.', brief='Translate a connection to the land into an identity with contemporary clarity.', idea='Aerial imagery becomes a flexible visual system. Organic texture and a compact wordmark bring the physical and digital worlds together.', palette=['#243e29','#d9ff70','#e9e9dd']),
]

def header():
    return '''<a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="wordmark" href="index.html" aria-label="Atelier home">atelier<span>®</span></a><nav aria-label="Main navigation"><a href="index.html#work">Work <span>03</span></a><a href="index.html#studio">Studio</a><a href="mailto:hello@example.com">Get in touch <span aria-hidden="true">↗</span></a></nav></header>'''

def footer():
    return '''<footer id="contact"><div class="footer-top"><p>Have something in mind?</p><a href="mailto:hello@example.com">Let’s make it matter. <span aria-hidden="true">↗</span></a></div><a class="footer-wordmark" href="index.html" aria-label="Atelier home">atelier.</a><div class="footer-bottom"><p>Independent by nature.</p><a href="mailto:hello@example.com">hello@example.com ↗</a><a href="CREDITS.html">Template & image credits</a><a href="#top">Back to top ↑</a></div></footer>'''

def page(title, desc, main):
    return f'''<!doctype html><html lang="en" id="top"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(desc)}"><title>{escape(title)} · Atelier</title><link rel="icon" href="assets/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"></head><body>{header()}<main id="main">{main}</main>{footer()}</body></html>'''

rows = ''.join(f'''<article class="project-row project-row-{i}"><div class="project-meta"><span class="eyebrow">0{i+1} / Concept study</span><h3><a href="{p['slug']}.html">{p['name']}</a></h3><p>{p['category']}</p><a class="text-link" href="{p['slug']}.html">Explore the project <span aria-hidden="true">↗</span></a></div><a class="project-image" href="{p['slug']}.html" aria-label="Explore {p['name']}"><img src="assets/{p['image']}" width="1200" height="800" loading="lazy" alt="{escape(p['intro'])}"><span class="image-arrow" aria-hidden="true">↗</span></a></article>''' for i,p in enumerate(PROJECTS))
home = f'''<section class="hero"><div class="hero-overline"><span class="eyebrow">Independent design practice</span><span class="eyebrow">Strategy / Identity / Digital</span></div><h1><span class="hero-first">Independent ideas.</span><span class="hero-second"><span>Distinct </span><em><span>identities.</span></em></span></h1><div class="hero-bottom"><a class="round-arrow" href="#work" aria-label="Explore selected work">↓</a><p>We shape thoughtful identities and digital experiences.<br>For ideas with somewhere to go.</p><span class="hero-index">A to Z<br>Ideas into form.</span></div></section><section class="work" id="work"><div class="section-heading"><h2>Selected work</h2><span>Three concept studies / 01 to 03</span></div>{rows}</section><section id="studio" class="studio"><div class="section-heading"><h2>The practice</h2><span>Small details. A wider view.</span></div><div class="studio-intro"><span class="eyebrow">01 / How we think</span><div><h2>Good design begins<br>with a better question.</h2><p>What needs to be said? Who needs to hear it? And what would make it feel unmistakably yours? We start there, then bring strategy, identity and digital design together around one clear idea.</p><a class="text-link" href="mailto:hello@example.com">Tell us what you’re thinking ↗</a></div></div><div class="services"><span class="eyebrow">02 / What we do</span><div class="service-list"><details><summary><span>01</span><span>Find the direction</span><span class="plus" aria-hidden="true">+</span></summary><p>Positioning, naming and creative strategy. A clear foundation for the decisions that follow.</p></details><details><summary><span>02</span><span>Shape the identity</span><span class="plus" aria-hidden="true">+</span></summary><p>Visual identities, art direction and design systems. A coherent language with enough room to grow.</p></details><details><summary><span>03</span><span>Build the experience</span><span class="plus" aria-hidden="true">+</span></summary><p>Websites, product direction and digital experiences. Thoughtful design that makes the next step feel natural.</p></details></div></div></section>'''
(OUT/'index.html').write_text(page('An independent design practice','Atelier is an editorial portfolio template for independent creative practices, adapted from Dante.',home))
for i,p in enumerate(PROJECTS):
    next_p=PROJECTS[(i+1)%len(PROJECTS)]
    swatches=''.join(f'<div style="--swatch:{c}"><span>{c.upper()}</span></div>' for c in p['palette'])
    main=f'''<section class="case-hero"><a class="text-link" href="index.html#work">← Selected work</a><div class="case-title"><h1><span>{p['name']}</span><span class="registration">®</span></h1><p>{p['line']}</p></div><div class="case-data"><span>{p['category']}</span><span>Concept study / 0{i+1}</span></div></section><figure class="case-cover"><img src="assets/{p['image']}" width="1200" height="800" alt="{escape(p['intro'])}"></figure><section class="case-story"><span class="eyebrow">The starting point</span><div><h2>{p['brief']}</h2><p>{p['intro']}</p><p>{p['idea']}</p></div></section><section class="palette-section"><div class="section-heading"><h2>A considered palette</h2><span>Colour / Material / Contrast</span></div><div class="swatches">{swatches}</div></section><section class="case-composition"><div class="case-crop"><img src="assets/{p['image']}" width="1200" height="800" alt="Detail of the {p['name']} identity study" loading="lazy"></div><div class="case-note"><span class="eyebrow">In the detail</span><p>{p['line']}</p><span class="small-note">Illustrative concept work.<br>Photography and artwork from the Dante demo collection.</span></div></section><section class="next-project"><span class="eyebrow">Next study / 0{(i+1)%len(PROJECTS)+1}</span><a href="{next_p['slug']}.html">{next_p['name']} <span aria-hidden="true">↗</span></a></section>'''
    (OUT/(p['slug']+'.html')).write_text(page(p['name'],p['intro'],main))
credits='''<section class="credits"><span class="eyebrow">Source & provenance</span><h1>Built on<br>shared foundations.</h1><p>Atelier is a Plotform-authored adaptation of <a href="https://github.com/JustGoodUI/dante-astro-theme">Dante by Just Good UI</a>, distributed under GPL-3.0. The original source and this adaptation are included in the downloadable source archive.</p><p>The project photographs and graphic compositions come from the original Dante demo collection, whose README credits Unsplash photography. These are illustrative concept studies, not claims of commissioned work or client results.</p><p>Newsreader and Geist fonts are bundled locally under the SIL Open Font License. This template uses no analytics, remote scripts, generated imagery or external font services.</p><p>The contact links open your email application. Replace the example email address with your own before publishing.</p><p><a class="text-link" href="template-source.zip" download>Download the complete source ↗</a></p><p><a href="LICENSE">Read the GPL-3.0 license</a></p></section>'''
(OUT/'CREDITS.html').write_text(page('Credits','Atelier source, image and font credits.',credits))
